insert into public.cursos (slug, nombre, descripcion, incluye, no_incluye, modalidad, foto_url, orden) values ('curso-extensiones-pestanas', 'Curso de Extensiones de Pestañas', 'Aprendé desde cero la técnica de extensiones de pestañas, con práctica guiada y acompañamiento personalizado.', array['Cuadernillo', 'Certificado', 'Material para principiante', 'Soporte de carrera durante 6 meses']::text[], array['Kit']::text[], 'Presencial', '/fotos/cursos/curso-pestanas.webp', 1) on conflict (slug) do nothing;
insert into public.cursos (slug, nombre, descripcion, incluye, no_incluye, modalidad, foto_url, orden) values ('curso-cejas', 'Curso de Cejas', 'Diseño, perfilado y técnicas de cejas para que empieces a trabajar con seguridad.', array['Cuadernillo', 'Certificado', 'Material para principiante', 'Soporte de carrera durante 6 meses']::text[], array['Kit']::text[], 'Presencial', '/fotos/cursos/curso-cejas.webp', 2) on conflict (slug) do nothing;
  insert into public.faq (pregunta, respuesta, orden) values ('¿Cómo reservo un turno?', 'Las reservas se hacen únicamente por WhatsApp. Escribime con el servicio que te interesa y te paso los días y horarios disponibles.', 1);
  insert into public.faq (pregunta, respuesta, orden) values ('¿Hay que pagar una seña?', 'Sí. Para confirmar tu turno se abona una seña de {sena} por transferencia. Ese monto se descuenta del total el día de tu cita.', 2);
  insert into public.faq (pregunta, respuesta, orden) values ('¿Qué medios de pago aceptan?', '{medios_pago}.', 3);
  insert into public.faq (pregunta, respuesta, orden) values ('¿Cuánto dura la cita?', 'Aproximadamente 2 horas, según el servicio. Te recomiendo venir con tiempo y sin maquillaje en la zona a trabajar.', 4);
  insert into public.faq (pregunta, respuesta, orden) values ('¿Puedo cambiar o cancelar mi turno?', 'Sí, avisame con anticipación por WhatsApp y buscamos otro día y horario.', 5);
  insert into public.faq (pregunta, respuesta, orden) values ('¿Cuál es el horario y dónde queda el estudio?', 'Atiendo {horario}. El estudio queda en {direccion}. Pedime la ubicación exacta por WhatsApp.', 6);
